<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides shift swap request behavior within the WorkIntel application. */ class ShiftSwapRequest extends Model { protected $fillable=['workspace_id','assignment_id','requested_by_member_id','target_member_id','request_type','status','message','reviewed_by','reviewed_at','review_note']; /** Defines attribute casting rules for the model. */ protected function casts():array{return ['reviewed_at'=>'datetime'];} /** Handles the assignment operation for the current WorkIntel workflow. */ public function assignment():BelongsTo{return $this->belongsTo(ShiftAssignment::class,'assignment_id');} /** Handles the requester operation for the current WorkIntel workflow. */ public function requester():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'requested_by_member_id');} /** Handles the target operation for the current WorkIntel workflow. */ public function target():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'target_member_id');} }
